    try {
        let result = await globalCommon.isMultilungalSupported(props?.siteUrl, props?.SmartMetadataListID);
        if (result?.supportedLanguagesSelected?.length> 0) {
            setSupportedLanguages(result.supportedLanguagesSelected);
        }
        if (result?.result !== undefined) {
            setIsShowLanIcon(result.result);
        }
        setLoadcomponent(true);
